import zipfile, re
import xml.etree.ElementTree as ET

NS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"

with zipfile.ZipFile("budget.xlsx") as z:
    tree = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

def col_num(ref):
    n = 0
    for ch in re.sub(r"[0-9]", "", ref):
        n = n * 26 + (ord(ch) - 64)
    return n

expenses = []
for row in tree.iter(NS + "row"):
    r_idx = int(row.get("r"))
    if not (11 <= r_idx <= 22):
        continue
    vals = {}
    for c in row.findall(NS + "c"):
        vals[col_num(c.get("r"))] = c.find(NS + "v").text
    expenses.append((r_idx, vals.get(1, ""), vals.get(2, ""), float(vals.get(3, 0))))

by_cat = {}
for r, cat, item, amt in expenses:
    by_cat.setdefault(cat, []).append((item, amt))
    print(f"Row {r}: {cat} / {item} = {amt}")

print()
for cat, items in by_cat.items():
    sub = sum(a for _, a in items)
    print(f"{cat}: {sub}")
print(f"\nTOTAL EXPENSES: {sum(a for _, _, _, a in expenses)}")

import zipfile, re
import xml.etree.ElementTree as ET

NS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"

with zipfile.ZipFile("budget.xlsx") as z:
    tree = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

def col_num(ref):
    n = 0
    for ch in re.sub(r"[0-9]", "", ref):
        n = n * 26 + (ord(ch) - 64)
    return n

def cell_text(c):
    t = c.get("t")
    v = c.find(NS + "v")
    if v is None:
        return ""
    if t == "inlineStr":
        is_el = c.find(NS + "is")
        return "".join(x.text or "" for x in is_el.iter(NS + "t"))
    return v.text

expenses = []
for row in tree.iter(NS + "row"):
    r_idx = int(row.get("r"))
    if not (11 <= r_idx <= 22):
        continue
    vals = {col_num(c.get("r")): cell_text(c) for c in row.findall(NS + "c")}
    amt = float(vals.get(3, 0) or 0)
    expenses.append((r_idx, vals.get(1, ""), vals.get(2, ""), amt))

by_cat = {}
for r, cat, item, amt in expenses:
    by_cat.setdefault(cat, []).append((item, amt))
    print(f"Row {r}: {cat} / {item} = {amt}")

print()
for cat, items in by_cat.items():
    print(f"{cat}: {sum(a for _, a in items)}")
print(f"\nTOTAL EXPENSES: {sum(a for _, _, _, a in expenses)}")

